// CONSTANTS
// =================================================================================================

const COMPONENT: &str = "miden-funding-service";

/// Tracing target used for user-visible events.
pub const LOG_TARGET: &str = "user::miden-funding-service";

/// Default largest amount one request may ask for, in base units of the native asset.
pub const DEFAULT_MAX_AMOUNT: u64 = 1_000_000_000;

/// Default largest number of notes one funding transaction creates.
pub const DEFAULT_MAX_NOTES_PER_TX: NonZeroUsize =
    NonZeroUsize::new(16).expect("literal is non-zero");

/// The node limits how many note IDs one lookup may hold, and the service looks up a whole
/// transaction's notes at once.
const _: () = assert!(DEFAULT_MAX_NOTES_PER_TX.get() <= MAX_NOTES_PER_TX.get());

/// Hard bound on `--max-notes-per-tx`.
pub const MAX_NOTES_PER_TX: NonZeroUsize = NonZeroUsize::new(100).expect("literal is non-zero");

/// Default number of blocks after its reference block at which a funding transaction expires.
pub const DEFAULT_TX_EXPIRATION_DELTA: NonZeroU16 =
    NonZeroU16::new(50).expect("literal is non-zero");

/// Default interval at which the service asks the node whether its notes are committed.
pub const DEFAULT_POLL_INTERVAL: Duration = Duration::from_secs(1);

/// Default timeout of a request to the node's RPC API.
pub const DEFAULT_RPC_TIMEOUT: Duration = Duration::from_secs(10);

/// Default timeout of a request to the remote prover.
pub const DEFAULT_TX_PROVER_TIMEOUT: Duration = Duration::from_secs(60);

/// Default timeout of a gRPC request served by this service.
pub const DEFAULT_GRPC_TIMEOUT: Duration = Duration::from_secs(300);

/// How often the service reads the funding account while no request arrives.
const STATUS_REFRESH_INTERVAL: Duration = Duration::from_secs(30);

/// How many requests may wait in the queue, per note of one transaction.
const QUEUE_CAPACITY_PER_TX: usize = 4;

// CONFIGURATION
// =================================================================================================

/// The configuration of the funding service.
pub struct FundingServiceConfig {
    rpc_url: Url,
    account_file: PathBuf,
    validator_signing_public_keys: Vec<ValidatorPublicKey>,
    tx_prover_url: Option<Url>,
    grpc_timeout: Duration,
    rpc_timeout: Duration,
    tx_prover_timeout: Duration,
    max_amount: u64,
    max_notes_per_tx: NonZeroUsize,
    tx_expiration_delta: NonZeroU16,
    poll_interval: Duration,
}

impl FundingServiceConfig {
    /// Creates a configuration with default timeouts and limits.
    pub fn new(
        rpc_url: Url,
        account_file: PathBuf,
        validator_signing_public_keys: Vec<ValidatorPublicKey>,
    ) -> Self {
        Self {
            rpc_url,
            account_file,
            validator_signing_public_keys,
            tx_prover_url: None,
            grpc_timeout: DEFAULT_GRPC_TIMEOUT,
            rpc_timeout: DEFAULT_RPC_TIMEOUT,
            tx_prover_timeout: DEFAULT_TX_PROVER_TIMEOUT,
            max_amount: DEFAULT_MAX_AMOUNT,
            max_notes_per_tx: DEFAULT_MAX_NOTES_PER_TX,
            tx_expiration_delta: DEFAULT_TX_EXPIRATION_DELTA,
            poll_interval: DEFAULT_POLL_INTERVAL,
        }
    }

    /// Sets the remote prover to use. Without one the service proves locally.
    #[must_use]
    pub fn with_tx_prover_url(mut self, url: Option<Url>) -> Self {
        self.tx_prover_url = url;
        self
    }

    #[must_use]
    pub fn with_grpc_timeout(mut self, timeout: Duration) -> Self {
        self.grpc_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_rpc_timeout(mut self, timeout: Duration) -> Self {
        self.rpc_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_tx_prover_timeout(mut self, timeout: Duration) -> Self {
        self.tx_prover_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_max_amount(mut self, max_amount: u64) -> Self {
        self.max_amount = max_amount;
        self
    }

    #[must_use]
    pub fn with_max_notes_per_tx(mut self, max_notes_per_tx: NonZeroUsize) -> Self {
        self.max_notes_per_tx = max_notes_per_tx;
        self
    }

    #[must_use]
    pub fn with_tx_expiration_delta(mut self, delta: NonZeroU16) -> Self {
        self.tx_expiration_delta = delta;
        self
    }

    #[must_use]
    pub fn with_poll_interval(mut self, interval: Duration) -> Self {
        self.poll_interval = interval;
        self
    }

    /// Connects to the node and builds the service.
    pub async fn build(self) -> anyhow::Result<FundingService> {
        anyhow::ensure!(
            self.max_notes_per_tx <= MAX_NOTES_PER_TX,
            "--max-notes-per-tx must not exceed {MAX_NOTES_PER_TX} because the node limits how \
             many note IDs one lookup may hold",
        );

        let funder_key = FunderKey::load(&self.account_file)
            .context("failed to load the funding account file")?;

        let node = RpcNodeClient::connect(
            &self.rpc_url,
            self.rpc_timeout,
            self.validator_signing_public_keys,
        )
        .await
        .context("failed to connect to the node RPC API")?;

        let fee_parameters = node.genesis_header().fee_parameters().clone();
        let fee_faucet_id = fee_parameters.fee_faucet_id();
        let verification_base_fee = fee_parameters.verification_base_fee();

        // A note holds the amount as a fungible asset, so an amount the asset type cannot express
        // must fail at startup instead of on every request.
        FungibleAsset::new(fee_faucet_id, self.max_amount)
            .context("--max-amount is not a valid amount of the native asset")?;

        let prover = match self.tx_prover_url {
            Some(url) => Prover::remote(url, self.tx_prover_timeout)
                .context("failed to build the remote prover client")?,
            None => Prover::local(),
        };

        info!(
            target: LOG_TARGET,
            "Funding service initialized",
            account.id = funder_key.account_id(),
            asset.faucet_id = fee_faucet_id,
            fee.verification_base_fee = verification_base_fee,
            funding_service.max_amount = self.max_amount,
            funding_service.max_notes_per_tx = self.max_notes_per_tx.get(),
            funding_service.tx_expiration_delta = self.tx_expiration_delta.get(),
            funding_service.remote_prover = matches!(prover, Prover::Remote(_))
        );

        Ok(FundingService {
            node,
            prover,
            funder_key,
            fee_faucet_id,
            verification_base_fee,
            worker_config: WorkerConfig {
                max_notes_per_tx: self.max_notes_per_tx,
                expiration_delta: self.tx_expiration_delta,
                poll_interval: self.poll_interval,
            },
            max_amount: self.max_amount,
            grpc_timeout: self.grpc_timeout,
        })
    }
}

// FUNDING SERVICE
// =================================================================================================

/// The funding service, ready to run.
pub struct FundingService {
    node: RpcNodeClient,
    prover: Prover,
    funder_key: FunderKey,
    fee_faucet_id: AccountId,
    verification_base_fee: u32,
    worker_config: WorkerConfig,
    max_amount: u64,
    grpc_timeout: Duration,
}

impl FundingService {
    /// Runs the gRPC server, the status refresher and the funding worker until one of them stops.
    pub async fn run(
        self,
        listener: TcpListener,
        shutdown: CancellationToken,
    ) -> anyhow::Result<()> {
        let (health_reporter, health_service) = tonic_health::server::health_reporter();
        health_reporter
            .set_service_status(
                funding_service_api::service_name(),
                tonic_health::ServingStatus::Serving,
            )
            .await;

        let status = StatusSnapshot::new(self.funder_key.account_id(), self.max_amount);
        let (requests, request_receiver) =
            mpsc::channel(QUEUE_CAPACITY_PER_TX * self.worker_config.max_notes_per_tx.get());

        let mut tasks = Tasks::new();

        let server = FundingRpcServer::new(requests, status.clone(), self.grpc_timeout);
        let server_shutdown = shutdown.clone();
        tasks.spawn("grpc-server", async move {
            server
                .serve(listener, health_service, server_shutdown)
                .await
                .context("the funding service gRPC server failed")
        });

        let refresher = StatusRefresher::new(
            self.node.clone(),
            self.funder_key.account_id(),
            self.fee_faucet_id,
            status.clone(),
            STATUS_REFRESH_INTERVAL,
        );
        let refresher_shutdown = shutdown.clone();
        tasks.spawn("status-refresher", async move {
            refresher
                .run(refresher_shutdown)
                .await
                .context("the funding service status refresher failed")
        });

        let funder = Funder::new(
            self.node,
            self.prover,
            FunderSetup {
                key: self.funder_key,
                fee_faucet_id: self.fee_faucet_id,
                verification_base_fee: self.verification_base_fee,
                config: self.worker_config,
                status,
            },
        );
        let worker_shutdown = shutdown.clone();
        tasks.spawn("funder", async move {
            funder
                .run(request_receiver, worker_shutdown)
                .await
                .context("the funding worker failed")
        });

        tasks
            .join_next_or_cancelled(shutdown)
            .await
            .context("a funding service task failed")
    }
}
